import{_ as i,b as r,c as o,g as n}from"./chunks/framework.86O3EbG5.js";const h=JSON.parse('{"title":"电影摄影：理论与实践","description":"","frontmatter":{"title":"电影摄影：理论与实践","subTitle":"视觉语言","author":"oasis","date":"2026-09-21T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/cinematography-theory-and-practice/2.md","filePath":"articles/books/cinematography-theory-and-practice/2.md"}'),s={name:"articles/books/cinematography-theory-and-practice/2.md"};function l(g,t,e,a,d,c){return r(),o("div",null,[...t[0]||(t[0]=[n('<h2 id="图画的作用" tabindex="-1">图画的作用</h2><p>画面是传达信息的。拍摄照片实际上也是在传达信息。一幅图像能够传递意义、风格、语气、气氛和其本身的潜台词。</p><h2 id="设计原则" tabindex="-1">设计原则</h2><ul><li><strong>整体性</strong>：视觉的结构必须整体、独立和完整。</li><li><strong>平衡</strong>：视觉平衡是构图的重要部分，构图中的每个视觉元素都有视觉比重。</li><li><strong>视觉张力</strong>：视觉元素之间的互相影响以及它们在画面中的位置，产生视觉张力。</li><li><strong>节奏</strong>：视觉元素的重复和近似重复，能够产生构图的形式感。</li><li><strong>比例</strong>：利用黄金分割决定比例和大小关系。</li><li><strong>对比</strong>：通过相反的事物来理解其本身。</li><li><strong>质感</strong>：质感和文化种族也有一些关系。</li><li><strong>指向性</strong>：所有事物都具有指向性，它是视觉构图中的关键元素，决定事物如何在视觉层面发挥作用，以及如何影响其他视觉元素。</li></ul><h2 id="产生景深的方法" tabindex="-1">产生景深的方法</h2><ul><li><strong>重叠</strong>：前景、中景、背景。</li><li><strong>改变尺寸</strong>：同类物体越远，在画面中通常越小。</li><li><strong>垂直位置</strong>：越靠近画面上方，我们往往认为它越远。物体在画面中的垂直位置，可以暗示它在空间中的远近。</li><li><strong>水平位置</strong>：水平位置本身不是天然的远近线索。它通常和空间结构结合使用。</li><li><strong>线性透视</strong>：线条向同一个方向收缩，大脑推断空间正在向远处延伸。</li><li><strong>前缩透视</strong>：这个物体不是平面的，它正朝着我的方向延伸。</li><li><strong>明暗对比</strong>：主体亮、背景暗。</li><li><strong>大气透视</strong>：远处的东西通常对比度降低、细节减少、颜色变淡、更偏向环境色。</li></ul><h2 id="视觉构图" tabindex="-1">视觉构图</h2><ul><li><strong>直线构图</strong>：稳定、秩序、力量、方向。</li><li><strong>曲线构图</strong>：流动、柔和、连续。</li><li><strong>三角形构图</strong>：画面中的三个视觉重点形成稳定关系。</li><li><strong>水平构图</strong>：稳定、平静、开阔。</li><li><strong>竖直构图</strong>：高度、力量、向上。</li><li><strong>对角线构图</strong>：制造运动感和方向感。</li><li><strong>水平线和消失点</strong>：地平线决定你观察空间的高度。消失点决定空间线条的方向。</li><li><strong>画框</strong>：排除不相干物体。</li><li><strong>开放画面与闭合画面</strong>：开放画面让观众意识到「画面之外还有世界」。</li><li><strong>平衡与不平衡的画面</strong></li><li><strong>正空间和留白</strong>：正空间是画面中被主体占据的区域。</li></ul><h2 id="构图的多种法则" tabindex="-1">构图的多种法则</h2><h3 id="人物构图法则" tabindex="-1">人物构图法则</h3><ul><li><strong>头上空间</strong></li><li><strong>鼻前空间</strong>：视线空间</li></ul>',11)])])}const p=i(s,[["render",l]]);export{h as __pageData,p as default};
